export { RouteDrawer } from './route-drawer.js';
export { RouteDialog } from './route-dialog.js';
export { RoutePage } from './route-page.js';
export { useRefineUnsavedChangesGuard } from './use-refine-unsaved-changes.js';

import { Dialog as DialogPrimitive } from '@base-ui/react/dialog';
import { X } from 'lucide-react';
import { type ReactNode, useCallback, useContext } from 'react';
import {
  RouteOverlayDepthContext,
  RouteSurfaceContext,
  type RouteSurfaceBeforeClose,
  useRouteSurfaceState,
} from '@nocobase/app-portal-sdk/routing';

import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { useRouteOverlayViewportStyle } from './route-overlay-viewport.js';

export function RouteDialog({
  title,
  description,
  actions,
  children,
  closeLabel,
  closeTo,
  beforeClose,
  className,
  nested,
}: {
  title: ReactNode;
  description?: ReactNode;
  actions?: ReactNode;
  children: ReactNode;
  closeLabel: string;
  closeTo: string;
  beforeClose?: RouteSurfaceBeforeClose;
  className?: string;
  nested?: ReactNode;
}) {
  const parentOverlayDepth = useContext(RouteOverlayDepthContext);
  const overlayViewportStyle = useRouteOverlayViewportStyle();
  const isNestedOverlay = parentOverlayDepth > 0;
  const { open, setOpen, close, navigateAfterClose } = useRouteSurfaceState({
    closeTo,
    beforeClose,
    animated: true,
  });
  const handleOpenChange = useCallback(
    (
      nextOpen: boolean,
      eventDetails: DialogPrimitive.Root.ChangeEventDetails,
    ) => {
      if (nextOpen) {
        setOpen(true);
        return;
      }

      eventDetails.cancel();
      void close();
    },
    [close, setOpen],
  );

  return (
    <RouteSurfaceContext.Provider value={close}>
      <RouteOverlayDepthContext.Provider value={parentOverlayDepth + 1}>
        <DialogPrimitive.Root
          open={open}
          onOpenChange={handleOpenChange}
          onOpenChangeComplete={(nextOpen) => {
            if (!nextOpen) navigateAfterClose();
          }}
        >
          <DialogPrimitive.Portal
            className='pointer-events-none fixed inset-y-0 right-0 left-0 z-50 transition-[right] duration-200 ease-in-out md:right-(--route-overlay-inline-end)'
            style={overlayViewportStyle}
          >
            {isNestedOverlay ? (
              <RouteDialogBackdrop open={open} onClose={close} />
            ) : (
              <DialogPrimitive.Backdrop
                className='pointer-events-auto absolute inset-0 bg-black/10 duration-150 supports-backdrop-filter:backdrop-blur-xs data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0'
                onClick={(event) => {
                  event.stopPropagation();
                  void close();
                }}
              />
            )}
            <DialogPrimitive.Popup
              className={cn(
                'pointer-events-auto absolute top-1/2 left-1/2 flex max-h-[calc(100dvh-2rem)] w-full max-w-[calc(100%-2rem)] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl bg-popover text-sm text-popover-foreground ring-1 ring-foreground/10 duration-150 outline-none sm:max-w-2xl data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95',
                className,
              )}
            >
              <header className='relative shrink-0 border-b px-5 py-4 pr-14 text-left'>
                <div className='flex items-start justify-between gap-4'>
                  <div className='min-w-0 space-y-1'>
                    <DialogPrimitive.Title className='font-heading truncate text-lg font-medium'>
                      {title}
                    </DialogPrimitive.Title>
                    {description ? (
                      <DialogPrimitive.Description className='text-sm text-muted-foreground'>
                        {description}
                      </DialogPrimitive.Description>
                    ) : null}
                  </div>
                  {actions ? (
                    <div className='flex shrink-0 items-center gap-2'>
                      {actions}
                    </div>
                  ) : null}
                </div>
                <Button
                  type='button'
                  variant='ghost'
                  size='icon-sm'
                  className='absolute top-3 right-3'
                  onClick={() => void close()}
                >
                  <X />
                  <span className='sr-only'>{closeLabel}</span>
                </Button>
              </header>
              {children}
            </DialogPrimitive.Popup>
          </DialogPrimitive.Portal>
          {nested}
        </DialogPrimitive.Root>
      </RouteOverlayDepthContext.Provider>
    </RouteSurfaceContext.Provider>
  );
}

function RouteDialogBackdrop({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => Promise<boolean>;
}) {
  return (
    <div
      role='presentation'
      aria-hidden='true'
      className={cn(
        'pointer-events-auto absolute inset-0 bg-black/10 transition-opacity duration-150 supports-backdrop-filter:backdrop-blur-xs',
        open ? 'opacity-100' : 'pointer-events-none opacity-0',
      )}
      onClick={(event) => {
        event.stopPropagation();
        void onClose();
      }}
    />
  );
}

import { Drawer as DrawerPrimitive } from '@base-ui/react/drawer';
import { X } from 'lucide-react';
import {
  type CSSProperties,
  type ReactNode,
  useCallback,
  useContext,
} from 'react';
import {
  RouteOverlayDepthContext,
  RouteSurfaceContext,
  type RouteSurfaceBeforeClose,
  useRouteSurfaceState,
} from '@nocobase/app-portal-sdk/routing';

import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { useRouteOverlayViewportStyle } from './route-overlay-viewport.js';

export function RouteDrawer({
  title,
  description,
  actions,
  children,
  closeLabel,
  closeTo,
  beforeClose,
  className,
  nested,
  stackOffset = '4rem',
}: {
  title: ReactNode;
  description?: ReactNode;
  actions?: ReactNode;
  children: ReactNode;
  closeLabel: string;
  closeTo: string;
  beforeClose?: RouteSurfaceBeforeClose;
  className?: string;
  nested?: ReactNode;
  stackOffset?: string;
}) {
  const parentOverlayDepth = useContext(RouteOverlayDepthContext);
  const overlayViewportStyle = useRouteOverlayViewportStyle();
  const isNestedOverlay = parentOverlayDepth > 0;
  const { open, setOpen, close, navigateAfterClose } = useRouteSurfaceState({
    closeTo,
    beforeClose,
    animated: true,
  });
  const handleOpenChange = useCallback(
    (
      nextOpen: boolean,
      eventDetails: DrawerPrimitive.Root.ChangeEventDetails,
    ) => {
      if (nextOpen) {
        setOpen(true);
        return;
      }

      eventDetails.cancel();
      void close();
    },
    [close, setOpen],
  );
  const stackStyle = {
    '--peek': stackOffset,
    '--stack-step': 0,
    '--bleed': '0px',
  } as CSSProperties;

  return (
    <RouteSurfaceContext.Provider value={close}>
      <RouteOverlayDepthContext.Provider value={parentOverlayDepth + 1}>
        <DrawerPrimitive.Root
          open={open}
          swipeDirection='right'
          onOpenChange={handleOpenChange}
          onOpenChangeComplete={(nextOpen) => {
            if (!nextOpen) navigateAfterClose();
          }}
        >
          <DrawerPrimitive.Portal
            className='pointer-events-none fixed inset-y-0 right-0 left-0 z-50 overflow-hidden transition-[right] duration-200 ease-in-out md:right-(--route-overlay-inline-end)'
            style={overlayViewportStyle}
          >
            {isNestedOverlay ? (
              <RouteDrawerBackdrop open={open} onClose={close} />
            ) : (
              <DrawerPrimitive.Backdrop
                className='pointer-events-auto absolute inset-0 bg-black/10 opacity-[max(var(--drawer-overlay-min-opacity,0),calc(1-var(--drawer-swipe-progress)))] transition-opacity duration-450 ease-[cubic-bezier(0.32,0.72,0,1)] select-none data-ending-style:pointer-events-none data-ending-style:opacity-0 data-starting-style:opacity-0 data-swiping:duration-0 supports-backdrop-filter:backdrop-blur-xs'
                onClick={(event) => {
                  event.stopPropagation();
                  void close();
                }}
              />
            )}
            <DrawerPrimitive.Viewport className='pointer-events-none absolute inset-0 select-none'>
              <DrawerPrimitive.Popup
                style={stackStyle}
                className={cn(
                  'group/route-drawer pointer-events-auto absolute inset-y-0 right-0 flex w-full transform-[translate3d(var(--translate-x,0px),0,0)] flex-row bg-popover text-sm text-popover-foreground shadow-xl transition-transform duration-450 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform outline-none sm:w-full lg:w-[min(42vw,100%)] lg:min-w-[min(40rem,100%)]',
                  '[--stack-peek-offset:max(0px,calc((var(--nested-drawers)-var(--stack-progress))*var(--peek)))] [--stack-progress:clamp(0,var(--drawer-swipe-progress),1)]',
                  '[--closed-transform:translate3d(calc(100%+2px),0,0)] [--translate-x:calc(var(--drawer-swipe-movement-x)-var(--stack-peek-offset))]',
                  'data-ending-style:transform-(--closed-transform) data-ending-style:opacity-[0.9999] data-starting-style:transform-(--closed-transform) data-swiping:duration-0 data-nested-drawer-swiping:duration-0',
                  'data-nested-drawer-open:overflow-hidden',
                  className,
                )}
              >
                <div
                  aria-hidden='true'
                  className='pointer-events-none absolute inset-0 z-20 bg-black/10 opacity-0 transition-opacity duration-450 ease-[cubic-bezier(0.22,1,0.36,1)] group-data-nested-drawer-open/route-drawer:opacity-100 supports-backdrop-filter:backdrop-blur-xs'
                />
                <DrawerPrimitive.Content className='flex min-h-0 flex-1 flex-col overflow-hidden overscroll-contain select-text group-data-swiping/route-drawer:select-none'>
                  <header className='relative shrink-0 border-b px-5 py-4 pr-14 text-left'>
                    <div className='flex items-start justify-between gap-4'>
                      <div className='min-w-0 space-y-1'>
                        <DrawerPrimitive.Title className='font-heading truncate text-lg font-medium text-foreground'>
                          {title}
                        </DrawerPrimitive.Title>
                        {description ? (
                          <DrawerPrimitive.Description className='text-sm text-balance text-muted-foreground'>
                            {description}
                          </DrawerPrimitive.Description>
                        ) : null}
                      </div>
                      {actions ? (
                        <div className='flex shrink-0 items-center gap-2'>
                          {actions}
                        </div>
                      ) : null}
                    </div>
                    <Button
                      type='button'
                      variant='ghost'
                      size='icon-sm'
                      className='absolute top-3 right-3'
                      onClick={() => void close()}
                    >
                      <X />
                      <span className='sr-only'>{closeLabel}</span>
                    </Button>
                  </header>
                  {children}
                </DrawerPrimitive.Content>
              </DrawerPrimitive.Popup>
            </DrawerPrimitive.Viewport>
          </DrawerPrimitive.Portal>
          {nested}
        </DrawerPrimitive.Root>
      </RouteOverlayDepthContext.Provider>
    </RouteSurfaceContext.Provider>
  );
}

function RouteDrawerBackdrop({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => Promise<boolean>;
}) {
  return (
    <div
      role='presentation'
      aria-hidden='true'
      className={cn(
        'pointer-events-auto absolute inset-0 bg-black/10 transition-opacity duration-450 ease-[cubic-bezier(0.32,0.72,0,1)] select-none supports-backdrop-filter:backdrop-blur-xs',
        open ? 'opacity-100' : 'pointer-events-none opacity-0',
      )}
      onClick={(event) => {
        event.stopPropagation();
        void onClose();
      }}
    />
  );
}

export function RouteDrawerFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'mt-auto flex shrink-0 flex-col gap-2 border-t px-5 py-4',
        className,
      )}
      {...props}
    />
  );
}

import { useContext, type CSSProperties } from 'react';
import { RouteOverlayViewportContext } from '@nocobase/app-portal-sdk/routing';

export function useRouteOverlayViewportStyle() {
  const viewport = useContext(RouteOverlayViewportContext);
  const inlineEnd = viewport?.inlineEnd ?? 0;

  return {
    '--route-overlay-inline-end':
      typeof inlineEnd === 'number' ? `${inlineEnd}px` : inlineEnd,
  } as CSSProperties;
}

import { type ReactNode } from 'react';
import {
  RouteSurfaceContext,
  type RouteSurfaceBeforeClose,
  useRouteSurfaceState,
} from '@nocobase/app-portal-sdk/routing';

export function RoutePage({
  children,
  closeTo,
  beforeClose,
}: {
  children: ReactNode;
  closeTo: string;
  beforeClose?: RouteSurfaceBeforeClose;
}) {
  const { close } = useRouteSurfaceState({
    closeTo,
    beforeClose,
    animated: false,
  });

  return (
    <RouteSurfaceContext.Provider value={close}>
      {children}
    </RouteSurfaceContext.Provider>
  );
}

import { useTranslate, useWarnAboutChange } from '@refinedev/core';
import { TriangleAlert } from 'lucide-react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';

type PendingConfirmation = {
  promise: Promise<boolean>;
  resolve: (allowed: boolean) => void;
};

export function useRefineUnsavedChangesGuard() {
  const translate = useTranslate();
  const { warnWhen, setWarnWhen } = useWarnAboutChange();
  const [open, setOpen] = useState(false);
  const pendingRef = useRef<PendingConfirmation | null>(null);

  const settle = useCallback(
    (allowed: boolean) => {
      const pending = pendingRef.current;
      if (!pending) return;

      pendingRef.current = null;
      if (allowed) setWarnWhen(false);
      setOpen(false);
      pending.resolve(allowed);
    },
    [setWarnWhen],
  );

  useEffect(
    () => () => {
      pendingRef.current?.resolve(false);
      pendingRef.current = null;
    },
    [],
  );

  const beforeClose = useCallback(() => {
    if (!warnWhen) return true;
    if (pendingRef.current) return pendingRef.current.promise;

    let resolve!: (allowed: boolean) => void;
    const promise = new Promise<boolean>((next) => {
      resolve = next;
    });
    pendingRef.current = { promise, resolve };
    setOpen(true);
    return promise;
  }, [warnWhen]);

  const confirmation = useMemo(
    () => (
      <AlertDialog
        open={open}
        onOpenChange={(nextOpen) => {
          if (!nextOpen) settle(false);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogMedia>
              <TriangleAlert />
            </AlertDialogMedia>
            <AlertDialogTitle>
              {translate('unsavedChanges.title', 'Discard unsaved changes?')}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {translate(
                'unsavedChanges.description',
                'Your changes have not been saved. Leaving now will discard them.',
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => settle(false)}>
              {translate('unsavedChanges.stay', 'Keep editing')}
            </AlertDialogCancel>
            <AlertDialogAction
              variant='destructive'
              onClick={() => settle(true)}
            >
              {translate('unsavedChanges.leave', 'Discard changes')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    ),
    [open, settle, translate],
  );

  return { beforeClose, confirmation };
}

export { default as KnowledgeBasesPage } from './page/knowledge-bases-page.js';
export { default as KnowledgeBaseWorkspacePage } from './page/knowledge-base-workspace-page.js';
export { default as KnowledgeBaseDocumentPage } from './page/document-page.js';
export { default as KnowledgeBaseSegmentRoute } from './page/segment-route-entry.js';
export { default as KnowledgeBaseRetrievalResultRoute } from './page/retrieval-result-route-entry.js';
export { default as KnowledgeBaseUploadController } from './page/upload-controller.js';
export * from './route-paths.js';
export * from './knowledge-base-routes.js';

import {
  knowledgeBaseDocumentPath,
  knowledgeBaseListPath,
  knowledgeBaseRetrievalPath,
  knowledgeBaseSegmentPath,
  knowledgeBaseUploadPath,
  knowledgeBaseWorkspacePath,
  vectorDatabasesPath,
} from './route-paths.js';
export const knowledgeBaseLiveRoutes = {
  list: knowledgeBaseListPath,
  vectors: vectorDatabasesPath,
  workspace: knowledgeBaseWorkspacePath,
  document: knowledgeBaseDocumentPath,
  segment: knowledgeBaseSegmentPath,
  upload: knowledgeBaseUploadPath,
  retrieval: knowledgeBaseRetrievalPath,
};

import {
  Outlet,
  useLocation,
  useNavigate,
  useOutletContext,
  useParams,
} from 'react-router';
import { Button } from '@/components/ui/button';
import { LoadingState } from '@/extensions/nocobase-ai-knowledge-base-components/app-shell-loading-state';
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
} from '@/components/ui/empty';
import { FileText } from 'lucide-react';
import {
  useKnowledgeBase,
  useKnowledgeBaseDocument,
  useKnowledgeBaseSegment,
} from '@/extensions/nocobase-ai-knowledge-base-providers';
import {
  KnowledgeBaseDirectoryError,
  SegmentList,
  SegmentTable,
} from '@/extensions/nocobase-ai-knowledge-base-components/index';
import {
  isLocalKnowledgeBase,
  canMaintainKnowledgeBaseDocument,
  type KnowledgeBase,
  type KnowledgeBaseDocument,
} from '@/extensions/nocobase-ai-knowledge-base-providers';
import { knowledgeBaseLiveRoutes } from '../knowledge-base-routes.js';
import {
  isLiveSegmentDrawerState,
  liveLocationPath,
  liveReturnTo,
} from './url-state.js';
import { useT } from '@/extensions/nocobase-ai-knowledge-base-components/locales';
import type { KnowledgeBaseWorkspaceOutletContext } from './knowledge-base-workspace-page.js';

export type LiveDocumentOutletContext = {
  knowledgeBase: KnowledgeBase;
  document: KnowledgeBaseDocument;
  canMaintainDocument: boolean;
};

export default function LiveDocumentPage() {
  const t = useT();
  const workspaceContext = useOutletContext<
    KnowledgeBaseWorkspaceOutletContext | undefined
  >();
  const { knowledgeBaseKey, documentId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const openedFromSegmentDrawer =
    isLiveSegmentDrawerState(location.state) ||
    new URLSearchParams(location.search).has('segmentsDocument');
  const knowledgeBase = useKnowledgeBase({
    knowledgeBaseKey,
    knowledgeBase: workspaceContext?.knowledgeBase,
  });
  const base = knowledgeBase.knowledgeBase;
  const local = !!base.data && isLocalKnowledgeBase(base.data);
  const documentState = useKnowledgeBaseDocument({
    knowledgeBaseKey: base.data?.key,
    documentId,
    document: { enabled: local },
  });
  const document = documentState.document;
  const isAuthorizedLocalDocument =
    local &&
    !!document.data &&
    document.data.knowledgeBaseKey === base.data!.key;
  const canMaintainDocument =
    !!document.data && canMaintainKnowledgeBaseDocument(document.data);
  const segmentState = useKnowledgeBaseSegment({
    knowledgeBaseKey: base.data?.key,
    documentId: document.data?.id,
    segments: {
      enabled: local && !!document.data && !openedFromSegmentDrawer,
      page: 1,
      pageSize: 20,
    },
  });
  const segments = segmentState.segments;
  const fallback = knowledgeBaseKey
    ? `${knowledgeBaseLiveRoutes.workspace(knowledgeBaseKey)}${location.search}${location.hash}`
    : knowledgeBaseLiveRoutes.list;
  const closeTo = knowledgeBaseKey
    ? liveReturnTo(
        location.state,
        fallback,
        knowledgeBaseLiveRoutes.workspace(knowledgeBaseKey),
      )
    : fallback;

  if (base.loading && !base.data) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <LoadingState className='min-h-64' />
      </main>
    );
  }
  if (base.error || !base.data) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <KnowledgeBaseDirectoryError
          error={
            base.error ??
            new Error(t('Knowledge base unavailable or not authorized.'))
          }
          onRetry={base.retry}
        />
      </main>
    );
  }
  if (!local) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <KnowledgeBaseDirectoryError
          error={
            new Error(
              t(
                'Documents and segments are unavailable for this knowledge base type.',
              ),
            )
          }
        />
      </main>
    );
  }
  if (document.loading && !document.data) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <LoadingState className='min-h-64' />
      </main>
    );
  }
  if (document.error || !document.data || !isAuthorizedLocalDocument) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <KnowledgeBaseDirectoryError
          error={
            document.error ??
            new Error(
              t(
                'Document unavailable or not authorized for this knowledge base.',
              ),
            )
          }
          onRetry={document.retry}
        />
      </main>
    );
  }

  const open = (uid: string) =>
    navigate(
      `${knowledgeBaseLiveRoutes.segment(base.data!.key, document.data!.id, uid)}${location.search}${location.hash}`,
      { state: { from: liveLocationPath(location) } },
    );
  const outletContext: LiveDocumentOutletContext = {
    knowledgeBase: base.data,
    document: document.data,
    canMaintainDocument,
  };

  if (openedFromSegmentDrawer) return <Outlet context={outletContext} />;
  return (
    <main className='space-y-5 px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
      <header className='flex flex-wrap items-start justify-between gap-3'>
        <div>
          <h1 className='font-heading text-2xl font-semibold'>
            {document.data.title || document.data.filename || t('Document')}
          </h1>
          <p className='text-muted-foreground'>
            {t('{{count}} segments', {
              count: document.data.segmentCount ?? 0,
            })}
          </p>
        </div>
        <Button variant='outline' onClick={() => navigate(closeTo)}>
          {t('Back to workspace')}
        </Button>
      </header>
      {!canMaintainDocument ? (
        <p className='rounded-xl border border-dashed p-4 text-sm text-muted-foreground'>
          {t(
            'You can view this shared document. Only its uploader can change segments, re-index, or delete it.',
          )}
        </p>
      ) : null}
      {segments.loading && !segments.data ? (
        <LoadingState className='min-h-48' />
      ) : segments.error ? (
        <KnowledgeBaseDirectoryError
          error={segments.error}
          onRetry={segments.retry}
        />
      ) : segments.data?.rows.length ? (
        <>
          <div className='hidden md:block'>
            <SegmentTable
              segments={segments.data.rows}
              onOpen={(segment) => open(segment.uid)}
            />
          </div>
          <div className='md:hidden'>
            <SegmentList
              segments={segments.data.rows}
              onOpen={(segment) => open(segment.uid)}
            />
          </div>
        </>
      ) : (
        <Empty className='min-h-48 border'>
          <EmptyHeader>
            <EmptyMedia variant='icon'>
              <FileText aria-hidden='true' />
            </EmptyMedia>
            <EmptyDescription>
              {t('This document has no segments yet.')}
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      )}
      <Outlet context={outletContext} />
    </main>
  );
}

import { useEffect, useState } from 'react';
import { useNotification } from '@refinedev/core';
import {
  CircleAlert,
  FileText,
  Minus,
  Plus,
  RefreshCw,
  Settings2,
} from 'lucide-react';
import { LoadingState } from '@/extensions/nocobase-ai-knowledge-base-components/app-shell-loading-state';
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
} from '@/components/ui/empty';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { useKnowledgeBaseSegment } from '@/extensions/nocobase-ai-knowledge-base-providers';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import {
  Sheet,
  SheetContent,
