import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
} from '@/components/ui/combobox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Sheet,
  SheetContent,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { useKnowledgeBaseService } from '@/extensions/nocobase-ai-knowledge-base-providers';
import type {
  KnowledgeBase,
  KnowledgeBaseType,
  KnowledgeBaseManagementOption,
  KnowledgeBaseManagementOptions,
  KnowledgeBaseMutation,
} from '@/extensions/nocobase-ai-knowledge-base-providers';
import { normalizeKnowledgeBaseMutation } from '@/extensions/nocobase-ai-knowledge-base-providers';
import { useT } from '@/extensions/nocobase-ai-knowledge-base-components/locales';

const defaultSegmentOptions = {
  enabled: true,
  chunkSize: 6000,
  chunkOverlap: 1200,
};
const emptyOptions: KnowledgeBaseManagementOptions = {
  vectorDatabases: [],
  llmServices: [],
  storages: [],
  externalProviders: [],
};
const knowledgeBaseTypeDetails: Record<
  KnowledgeBaseType,
  {
    label: 'Local' | 'Read-only' | 'External';
    description: string;
    badgeClassName: string;
  }
> = {
  LOCAL: {
    label: 'Local',
    description:
      'Suitable for knowledge bases where documents, segments, and vector data are maintained in the current system.',
    badgeClassName: 'bg-blue-50 text-blue-700 ring-blue-200',
  },
  READONLY: {
    label: 'Read-only',
    description:
      'Suitable for scenarios that only connect an existing vector database as the RAG retrieval source. Document maintenance and vectorization are completed by an external system.',
    badgeClassName: 'bg-muted text-muted-foreground ring-border',
  },
  EXTERNAL: {
    label: 'External',
    description:
      'Suitable for retrieval scenarios where you develop a plugin to connect external APIs or other vector databases.',
    badgeClassName: 'bg-purple-50 text-purple-700 ring-purple-200',
  },
};

function newKnowledgeBase(
  knowledgeBaseType: KnowledgeBaseType,
): KnowledgeBaseMutation {
  return {
    key: `kb-${Date.now().toString(36)}`,
    name: '',
    description: '',
    knowledgeBaseType,
    ...(knowledgeBaseType === 'LOCAL'
      ? { segmentOptions: defaultSegmentOptions }
      : {}),
    enabled: true,
  };
}

function editKnowledgeBase(record: KnowledgeBase): KnowledgeBaseMutation {
  return {
    key: record.key,
    name: record.name,
    description: record.description ?? '',
    knowledgeBaseType: record.knowledgeBaseType,
    enabled: record.enabled,
    disk: record.disk,
    vectorDatabaseKey: record.vectorDatabaseKey ?? record.vectorStoreConfigKey,
    vectorStoreConfigKey: record.vectorStoreConfigKey,
    llmService: record.llmService,
    embeddingModel: record.embeddingModel,
    vectorStoreProvider: record.vectorStoreProvider,
    vectorStoreProps: record.vectorStoreProps,
    segmentOptions: record.segmentOptions ?? defaultSegmentOptions,
  };
}

function OptionSelect({
  value,
  options,
  placeholder,
  disabled,
  onChange,
}: {
  value?: string;
  options: KnowledgeBaseManagementOption[];
  placeholder: string;
  disabled?: boolean;
  onChange: (value: string) => void;
}): ReactElement {
  return (
    <Select
      value={value ?? null}
      disabled={disabled}
      onValueChange={(next) => next && onChange(next)}
    >
      <SelectTrigger className='w-full'>
        <SelectValue>
          {value
            ? (options.find((option) => option.value === value)?.label ?? value)
            : placeholder}
        </SelectValue>
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

function EditableOptionInput({
  value,
  options,
  placeholder,
  disabled,
  onChange,
}: {
  value?: string;
  options: KnowledgeBaseManagementOption[];
  placeholder: string;
  disabled?: boolean;
  onChange: (value: string) => void;
}): ReactElement {
  const items = options.map((option) => option.value);
  return (
    <Combobox
      items={items}
      value={value ?? null}
      onValueChange={(next) => next && onChange(next)}
      onInputValueChange={onChange}
    >
      <ComboboxInput
        className='w-full'
        placeholder={placeholder}
        disabled={disabled}
        showClear
      />
      <ComboboxContent className='w-(--anchor-width) min-w-0'>
        <ComboboxEmpty>{placeholder}</ComboboxEmpty>
        <ComboboxList>
          {(item: string) => (
            <ComboboxItem key={item} value={item}>
              {options.find((option) => option.value === item)?.label ?? item}
            </ComboboxItem>
          )}
        </ComboboxList>
      </ComboboxContent>
    </Combobox>
  );
}

export function KnowledgeBaseEditorSheet({
  open,
  record,
  knowledgeBaseType,
  onOpenChange,
  onSaved,
}: {
  open: boolean;
  record?: KnowledgeBase;
  knowledgeBaseType: KnowledgeBaseType;
  onOpenChange: (open: boolean) => void;
  onSaved: () => void;
}): ReactElement {
  const t = useT();
  const service = useKnowledgeBaseService();
  const [values, setValues] = useState<KnowledgeBaseMutation>(() =>
    newKnowledgeBase(knowledgeBaseType),
  );
  const [options, setOptions] =
    useState<KnowledgeBaseManagementOptions>(emptyOptions);
  const [embeddingModels, setEmbeddingModels] = useState<
    KnowledgeBaseManagementOption[]
  >([]);
  const [loadingOptions, setLoadingOptions] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string>();
  const [externalProps, setExternalProps] = useState('[]');

  useEffect(() => {
    if (!open) return;
    const initial = record
      ? editKnowledgeBase(record)
      : newKnowledgeBase(knowledgeBaseType);
    setValues(initial);
    setExternalProps(JSON.stringify(initial.vectorStoreProps ?? [], null, 2));
    setEmbeddingModels([]);
    setError(undefined);
    setLoadingOptions(true);
    void service
      .listKnowledgeBaseManagementOptions()
      .then((loaded) => {
        setOptions(loaded);
        setValues((current) =>
          current.knowledgeBaseType === 'LOCAL' && !current.disk
            ? { ...current, disk: loaded.storages[0]?.value }
            : current,
        );
      })
      .catch((cause: unknown) =>
        setError(cause instanceof Error ? cause.message : String(cause)),
      )
      .finally(() => setLoadingOptions(false));
  }, [knowledgeBaseType, open, record, service]);

  useEffect(() => {
    if (
      !open ||
      !values.llmService ||
      values.knowledgeBaseType === 'EXTERNAL'
    ) {
      setEmbeddingModels([]);
      return;
    }
    void service
      .listEmbeddingModels(values.llmService)
      .then(setEmbeddingModels)
      .catch((cause: unknown) =>
        setError(cause instanceof Error ? cause.message : String(cause)),
      );
  }, [open, service, values.knowledgeBaseType, values.llmService]);

  const save = async (): Promise<void> => {
    if (!values.name.trim() || saving) return;
    setSaving(true);
    setError(undefined);
    try {
      if (!values.key?.trim()) throw new Error(t('Key is required.'));
      if (values.knowledgeBaseType !== 'EXTERNAL') {
        if (!values.vectorDatabaseKey)
          throw new Error(t('Select a vector database.'));
        if (!values.llmService) throw new Error(t('Select an LLM service.'));
        if (values.knowledgeBaseType === 'LOCAL' && !values.disk) {
          throw new Error(t('Select a file storage disk.'));
        }
      } else if (!values.vectorStoreProvider) {
        throw new Error(t('Select an external vector-store provider.'));
      }
      const visible = new Set<string>([
        'key',
        'name',
        'description',
        'knowledgeBaseType',
        'enabled',
      ]);
      if (values.knowledgeBaseType === 'LOCAL') visible.add('disk');
      if (values.knowledgeBaseType !== 'EXTERNAL') {
        visible.add('vectorDatabaseKey');
        visible.add('llmService');
        visible.add('embeddingModel');
      }
      if (local) visible.add('segmentOptions');
      if (external) visible.add('vectorStoreProps');
      let parsedExternalProps: KnowledgeBaseMutation['vectorStoreProps'];
      if (external) {
        try {
          const parsed: unknown = JSON.parse(externalProps);
          if (!Array.isArray(parsed))
            throw new Error('Provider properties must be a JSON array.');
          parsedExternalProps = parsed.flatMap(
            (
              value,
            ): NonNullable<
              KnowledgeBaseMutation['vectorStoreProps']
            >[number][] => {
              if (!value || typeof value !== 'object' || Array.isArray(value))
                return [];
              const item = value as Record<string, unknown>;
              return typeof item.key === 'string'
                ? [{ key: item.key, value: item.value }]
                : [];
            },
          );
        } catch (cause) {
          setError(cause instanceof Error ? cause.message : String(cause));
          setSaving(false);
          return;
        }
      }
      const payload = normalizeKnowledgeBaseMutation(
        {
          ...values,
          ...(external ? { vectorStoreProps: parsedExternalProps } : {}),
        },
        record,
        visible,
      );
      if (record) await service.updateKnowledgeBase(record.id, payload);
      else await service.createKnowledgeBase(payload);
      onOpenChange(false);
      onSaved();
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : String(cause));
    } finally {
      setSaving(false);
    }
  };

  const local = values.knowledgeBaseType === 'LOCAL';
  const external = values.knowledgeBaseType === 'EXTERNAL';
  const typeDetails = knowledgeBaseTypeDetails[values.knowledgeBaseType];
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side='right'
        className='w-full overflow-y-auto sm:max-w-none md:w-1/2'
      >
        <SheetHeader className='border-b px-6 py-5'>
          <SheetTitle>
            {record ? t('Edit knowledge base') : t('New knowledge base')}
          </SheetTitle>
        </SheetHeader>
        <form
          className='grid gap-5 px-6 pb-6'
          onSubmit={(event) => {
            event.preventDefault();
            void save();
          }}
        >
          <div className='grid gap-2 rounded-lg border bg-card p-4'>
            <div className='flex items-center gap-2'>
              <span className='text-sm font-semibold'>
                {t('Knowledge base type:')}
              </span>
              <span
                className={`inline-flex h-5 items-center rounded-full px-2 text-xs font-medium ring-1 ring-inset ${typeDetails.badgeClassName}`}
              >
                {t(typeDetails.label)}
              </span>
            </div>
            <p className='text-sm leading-5 text-muted-foreground'>
              {t(typeDetails.description)}
            </p>
          </div>
          <div className='grid gap-2'>
            <Label htmlFor='knowledge-base-key'>{t('Key')}</Label>
            <Input
              id='knowledge-base-key'
              value={values.key ?? ''}
              disabled={!!record}
              onChange={(event) =>
                setValues((current) => ({
                  ...current,
                  key: event.target.value,
                }))
              }
            />
          </div>
          <div className='grid gap-2'>
            <Label htmlFor='knowledge-base-name'>{t('Name')}</Label>
            <Input
              id='knowledge-base-name'
              autoFocus
              required
              value={values.name}
              onChange={(event) =>
                setValues((current) => ({
                  ...current,
                  name: event.target.value,
                }))
              }
            />
          </div>
          {local ? (
            <div className='grid gap-2'>
              <Label>{t('File storage')}</Label>
              <OptionSelect
                value={values.disk}
                options={options.storages}
                placeholder={
                  loadingOptions ? t('Loading…') : t('Select file storage')
                }
                disabled={loadingOptions || !!record}
                onChange={(disk) =>
                  setValues((current) => ({ ...current, disk }))
                }
              />
            </div>
          ) : null}
          {!external ? (
            <>
              <div className='grid gap-2'>
                <Label>{t('Vector database')}</Label>
                <OptionSelect
                  value={values.vectorDatabaseKey}
                  options={options.vectorDatabases}
                  placeholder={
                    loadingOptions ? t('Loading…') : t('Select vector database')
                  }
                  disabled={loadingOptions}
                  onChange={(vectorDatabaseKey) =>
                    setValues((current) => ({ ...current, vectorDatabaseKey }))
                  }
                />
              </div>
              <div className='grid gap-2'>
                <Label>{t('LLM service')}</Label>
                <OptionSelect
                  value={values.llmService}
                  options={options.llmServices}
                  placeholder={
                    loadingOptions ? t('Loading…') : t('Select LLM service')
                  }
                  disabled={loadingOptions}
                  onChange={(llmService) =>
                    setValues((current) => ({
                      ...current,
                      llmService,
                      embeddingModel: undefined,
                    }))
                  }
                />
              </div>
              <div className='grid gap-2'>
                <Label>{t('Embedding model')}</Label>
                <EditableOptionInput
                  value={values.embeddingModel}
                  options={embeddingModels}
                  placeholder={
                    values.llmService
                      ? t('Select or enter an embedding model')
                      : t('Select an LLM service first')
                  }
                  disabled={!values.llmService}
                  onChange={(embeddingModel) =>
                    setValues((current) => ({ ...current, embeddingModel }))
                  }
                />
              </div>
            </>
          ) : (
            <div className='grid gap-2'>
              <Label>{t('External vector-store provider')}</Label>
              <OptionSelect
                value={values.vectorStoreProvider}
                options={options.externalProviders}
                placeholder={
                  loadingOptions
                    ? t('Loading…')
                    : t('Select external vector-store provider')
                }
                disabled={loadingOptions || !!record}
                onChange={(vectorStoreProvider) =>
                  setValues((current) => ({
                    ...current,
                    vectorStoreProvider,
                  }))
                }
              />
            </div>
          )}
          <div className='grid gap-2'>
            <Label htmlFor='knowledge-base-description'>
              {t('Description')}
            </Label>
            <Textarea
              id='knowledge-base-description'
              rows={5}
              value={values.description ?? ''}
              onChange={(event) =>
                setValues((current) => ({
                  ...current,
                  description: event.target.value,
                }))
              }
            />
          </div>
          {external ? (
            <div className='grid gap-2'>
              <Label htmlFor='external-provider-properties'>
                {t('Provider properties')}
              </Label>
              <Textarea
                id='external-provider-properties'
                rows={8}
                className='font-mono text-xs'
                value={externalProps}
                onChange={(event) => setExternalProps(event.target.value)}
              />
              <p className='text-xs text-muted-foreground'>
                {t(
                  'Enter provider properties as a JSON array of key and value objects.',
                )}
              </p>
            </div>
          ) : null}
          {local ? (
            <>
              <div className='flex items-center justify-between gap-4'>
                <Label>{t('Split document')}</Label>
                <Switch
                  checked={values.segmentOptions?.enabled !== false}
                  onCheckedChange={(enabled) =>
                    setValues((current) => ({
                      ...current,
                      segmentOptions: {
                        ...defaultSegmentOptions,
                        ...current.segmentOptions,
                        enabled,
                      },
                    }))
                  }
                />
              </div>
              <div className='grid gap-2'>
                <Label htmlFor='chunk-size'>{t('Chunk size')}</Label>
                <Input
                  id='chunk-size'
                  className='w-36'
                  type='number'
                  min={1}
                  step={100}
                  value={
                    values.segmentOptions?.chunkSize ??
                    defaultSegmentOptions.chunkSize
                  }
                  onChange={(event) =>
                    setValues((current) => ({
                      ...current,
                      segmentOptions: {
                        ...defaultSegmentOptions,
                        ...current.segmentOptions,
                        chunkSize: Math.max(1, Number(event.target.value) || 1),
                      },
                    }))
                  }
                />
              </div>
              <div className='grid gap-2'>
                <Label htmlFor='chunk-overlap'>{t('Chunk overlap')}</Label>
                <Input
                  id='chunk-overlap'
                  className='w-36'
                  type='number'
                  min={0}
                  step={100}
                  value={
                    values.segmentOptions?.chunkOverlap ??
                    defaultSegmentOptions.chunkOverlap
                  }
                  onChange={(event) =>
                    setValues((current) => ({
                      ...current,
                      segmentOptions: {
                        ...defaultSegmentOptions,
                        ...current.segmentOptions,
                        chunkOverlap: Math.max(
                          0,
                          Number(event.target.value) || 0,
                        ),
                      },
                    }))
                  }
                />
              </div>
            </>
          ) : null}
          <div className='flex items-center justify-between gap-4'>
            <Label>{t('Enabled')}</Label>
            <Switch
              checked={values.enabled !== false}
              onCheckedChange={(enabled) =>
                setValues((current) => ({ ...current, enabled }))
              }
            />
          </div>
          {error ? (
            <p className='text-sm text-destructive' role='alert'>
              {error}
            </p>
          ) : null}
          <SheetFooter className='-mx-6 border-t px-6 pt-4'>
            <div className='flex justify-end gap-2'>
              <Button
                type='button'
                variant='outline'
                disabled={saving}
                onClick={() => onOpenChange(false)}
              >
                {t('Cancel')}
              </Button>
              <Button type='submit' disabled={saving || !values.name.trim()}>
                {saving ? t('Saving…') : t('Save')}
              </Button>
            </div>
          </SheetFooter>
        </form>
      </SheetContent>
    </Sheet>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { useNotification } from '@refinedev/core';
import {
  Link,
  Outlet,
  useLocation,
  useNavigate,
  useParams,
  useSearchParams,
} from 'react-router';
import {
  useKnowledgeBase,
  useKnowledgeBaseDocument,
} from '@/extensions/nocobase-ai-knowledge-base-providers';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import {
  ArrowLeft,
  CircleAlert,
  CircleFadingArrowUpIcon,
  FileText,
  RefreshCw,
  Search,
} from 'lucide-react';
import { LoadingState } from '@/extensions/nocobase-ai-knowledge-base-components/app-shell-loading-state';
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
} from '@/components/ui/empty';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { nocobaseClient } from '@nocobase/app-portal-sdk/client';
import {
  PagePagination,
  DocumentTable,
  KnowledgeBaseDirectoryError,
  KnowledgeBaseHitTests,
} from '@/extensions/nocobase-ai-knowledge-base-components/index';
import {
  isLocalKnowledgeBase,
  canMaintainKnowledgeBaseDocument,
  normalizeKnowledgeBaseError,
  type KnowledgeBase,
  type KnowledgeBaseDocument,
  type RecordId,
  type KnowledgeBaseSearchResult,
} from '@/extensions/nocobase-ai-knowledge-base-providers';
import { knowledgeBaseLiveRoutes } from '../knowledge-base-routes.js';
import {
  liveLocationPath,
  knowledgeBaseWorkspaceSearch,
  parseKnowledgeBaseWorkspaceState,
} from './url-state.js';
import { DocumentSegmentsDrawer } from './document-segments-drawer.js';
import { notifyKnowledgeBaseMutationError } from './notifications.js';
import { useT } from '@/extensions/nocobase-ai-knowledge-base-components/locales';

type DocumentAction = { kind: 'vectorize' | 'delete'; documentIds: RecordId[] };

export type KnowledgeBaseWorkspaceOutletContext = {
  knowledgeBase: KnowledgeBase;
  retrievalResults: KnowledgeBaseSearchResult[];
  onDocumentsRefresh: () => void;
};

export default function KnowledgeBaseWorkspacePage() {
  const t = useT();
  const { open: notify } = useNotification();
  const { knowledgeBaseKey } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const [params] = useSearchParams();
  const workspace = parseKnowledgeBaseWorkspaceState(params);
  const [queryDraft, setQueryDraft] = useState('');
  const [documentAction, setDocumentAction] = useState<DocumentAction>();
  const [segmentDocument, setSegmentDocument] =
    useState<KnowledgeBaseDocument>();
  const [segmentDrawerOpen, setSegmentDrawerOpen] = useState(false);
  const [documentActionPending, setDocumentActionPending] = useState(false);
  const knowledgeBase = useKnowledgeBase({
    knowledgeBaseKey,
    retrieval: {
      query: workspace.retrievalQuery,
      topK: workspace.topK,
      score: workspace.score,
    },
  });
  const base = knowledgeBase.knowledgeBase;
  const local = !!base.data && isLocalKnowledgeBase(base.data);
  const documentState = useKnowledgeBaseDocument({
    knowledgeBaseKey: base.data?.key,
    documents: {
      enabled: local,
      mode: 'paginated',
      page: workspace.documentPage,
      pageSize: workspace.documentPageSize,
    },
  });
  const { service } = documentState;
  const documents = documentState.documents.paginated;
  const retrieval = knowledgeBase.retrieval;
  const hasSubmittedRetrievalQuery = !!workspace.retrievalQuery;

  useEffect(() => {
    setQueryDraft('');
  }, [knowledgeBaseKey]);

  const setWorkspace = (next: Partial<typeof workspace>, replace = true) => {
    navigate(
      {
        pathname: location.pathname,
        search: knowledgeBaseWorkspaceSearch({ ...workspace, ...next }),
        hash: location.hash,
      },
      { replace },
    );
  };

  const resetHitTests = () => {
    setQueryDraft('');
    setWorkspace({ retrievalQuery: '', topK: 4, score: 0.6 });
  };
  useEffect(() => {
    if (!base.data || !workspace.segmentDocumentId) {
      return;
    }
    const requestedDocument = documents.data?.rows.find(
      (document) => String(document.id) === workspace.segmentDocumentId,
    );
    if (!requestedDocument) return;
    setSegmentDocument(requestedDocument);
    setSegmentDrawerOpen(true);
  }, [base.data, documents.data, workspace.segmentDocumentId]);

  const runDocumentAction = async () => {
    const activeAction = documentAction;
    if (
      !activeAction ||
      !base.data ||
      documentActionPending ||
      !activeAction.documentIds.length
    )
      return;
    setDocumentActionPending(true);
    try {
      if (activeAction.kind === 'vectorize') {
        await service.vectorizeDocuments({
          knowledgeBaseKey: base.data.key,
          documentIds: activeAction.documentIds,
        });
      } else {
        await service.deleteDocuments({
          documentIds: activeAction.documentIds,
        });
      }
      notify?.({
        type: 'success',
        message:
          activeAction.kind === 'vectorize'
            ? t('Re-indexing submitted')
            : t('Documents deleted'),
        description:
          activeAction.kind === 'vectorize'
            ? t(
                'Re-indexing was submitted. The status will update when processing finishes.',
              )
            : undefined,
      });
      setDocumentAction(undefined);
      documents.retry();
    } catch (error) {
      const message = t('Document action failed');
      notifyKnowledgeBaseMutationError(notify, message, error, message);
      setDocumentAction(undefined);
    } finally {
      setDocumentActionPending(false);
    }
  };

  const downloadDocument = async (record: KnowledgeBaseDocument) => {
    try {
      const downloadable = record.url
        ? record
        : await service.getDocument({
            knowledgeBaseKey: record.knowledgeBaseKey,
            documentId: record.id,
          });
      if (!downloadable.url) {
        throw new Error(t('The document file is unavailable.'));
      }

      const suffix = downloadable.extname
        ? downloadable.extname.startsWith('.')
          ? downloadable.extname
          : `.${downloadable.extname}`
        : '';
      const title = downloadable.title || record.title;
      const filename = title
        ? `${title}${suffix}`
        : downloadable.filename || `document-${downloadable.id}${suffix}`;
      const response = await fetch(
        nocobaseClient.resolveUrl(downloadable.url),
        {
          headers: nocobaseClient.getHeaders({
            method: 'GET',
            withAclMeta: false,
            headers: { Accept: '*/*' },
          }),
        },
      );
      if (!response.ok) {
        throw new Error(t('The document file is unavailable.'));
      }

      const objectUrl = URL.createObjectURL(await response.blob());
      const link = window.document.createElement('a');
      link.href = objectUrl;
      link.download = filename;
      link.rel = 'noopener noreferrer';
      window.document.body.appendChild(link);
      link.click();
      link.remove();
      window.setTimeout(() => URL.revokeObjectURL(objectUrl), 0);
    } catch (error) {
      notifyKnowledgeBaseMutationError(
        notify,
        t('Download failed'),
        error,
        t('The document file is unavailable.'),
      );
    }
  };
  const outletContext = useMemo<
    KnowledgeBaseWorkspaceOutletContext | undefined
  >(
    () =>
      base.data
        ? {
            knowledgeBase: base.data,
            retrievalResults: retrieval.data ?? [],
            onDocumentsRefresh: documents.retry,
          }
        : undefined,
    [base.data, documents.retry, retrieval.data],
  );

  if (base.loading && !base.data) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <LoadingState className='min-h-64' />
      </main>
    );
  }
  if (base.error || !base.data) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <KnowledgeBaseDirectoryError
          error={
            base.error ??
            new Error(t('Knowledge base unavailable or not authorized.'))
          }
          onRetry={base.retry}
        />
      </main>
    );
  }

  return (
    <main className='space-y-5 px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
      <Tabs
        defaultValue={local ? 'documents' : 'retrieve'}
        onValueChange={(value) => {
          if (value === 'retrieve') resetHitTests();
        }}
        className='gap-0'
      >
        <div className='flex items-center justify-between gap-3 border-b pb-3'>
          <TabsList className='h-auto rounded-lg border bg-muted/40 p-1'>
            {local ? (
              <TabsTrigger value='documents' className='gap-2 px-3 py-1.5'>
                <FileText aria-hidden='true' className='size-4' />
                {t('Documents')}
              </TabsTrigger>
            ) : null}
            <TabsTrigger value='retrieve' className='gap-2 px-3 py-1.5'>
              <Search aria-hidden='true' className='size-4' />
              {t('Hit tests')}
            </TabsTrigger>
          </TabsList>
          <Button
            type='button'
            variant='ghost'
            size='sm'
            className='shrink-0 text-muted-foreground'
            onClick={() => navigate(knowledgeBaseLiveRoutes.list)}
          >
            <ArrowLeft data-icon='inline-start' aria-hidden='true' />
            {t('Back')}
          </Button>
        </div>
        {local ? (
          <TabsContent value='documents' className='mt-5 space-y-3'>
            <section className='space-y-3'>
              <div className='flex items-center justify-between gap-3'>
                <p className='flex items-center gap-1.5 whitespace-nowrap text-sm text-muted-foreground'>
                  <CircleAlert
                    aria-hidden='true'
                    className='size-3.5 shrink-0'
                  />
                  <span>
                    {t(
                      'Upload a ZIP archive to import multiple documents in one go.',
                    )}
                  </span>
                </p>
                <div className='flex shrink-0 items-center gap-2'>
                  <Button
                    variant='outline'
                    size='sm'
                    disabled={documents.loading}
                    onClick={() => documents.retry()}
                  >
                    <RefreshCw data-icon='inline-start' aria-hidden='true' />
                    {t('Refresh')}
                  </Button>
                  <Button
                    size='sm'
                    render={
                      <Link
                        to={`${knowledgeBaseLiveRoutes.upload(base.data.key)}${location.search}${location.hash}`}
                        state={{ from: liveLocationPath(location) }}
                      />
                    }
                  >
                    <CircleFadingArrowUpIcon
                      data-icon='inline-start'
                      aria-hidden='true'
                    />
                    {t('Upload')}
                  </Button>
                </div>
              </div>
              {documents.loading && !documents.data ? (
                <LoadingState className='min-h-48' />
              ) : documents.error ? (
                <KnowledgeBaseDirectoryError
                  error={documents.error}
                  onRetry={documents.retry}
                />
              ) : documents.data?.rows.length ? (
                <DocumentTable
                  documents={documents.data.rows}
                  canMaintain={canMaintainKnowledgeBaseDocument}
                  onOpen={(document) => {
                    setSegmentDocument(document);
                    setSegmentDrawerOpen(true);
                    setWorkspace({ segmentDocumentId: String(document.id) });
                  }}
                  onDownload={downloadDocument}
                  onVectorize={(document) => {
                    setDocumentAction({
                      kind: 'vectorize',
                      documentIds: [document.id],
                    });
                  }}
                  onDelete={(document) => {
                    setDocumentAction({
                      kind: 'delete',
                      documentIds: [document.id],
                    });
                  }}
                />
              ) : (
                <Empty className='min-h-48 border'>
                  <EmptyHeader>
                    <EmptyMedia variant='icon'>
                      <FileText aria-hidden='true' />
                    </EmptyMedia>
                    <EmptyDescription>
                      {t('No documents are available in this knowledge base.')}
                    </EmptyDescription>
                  </EmptyHeader>
                </Empty>
              )}
              {documents.data ? (
                <PagePagination
                  page={documents.data.page}
                  pageSize={documents.data.pageSize}
                  total={documents.data.count}
                  onPageChange={(documentPage) =>
                    setWorkspace({ documentPage })
                  }
                  onPageSizeChange={(documentPageSize) =>
                    setWorkspace({ documentPage: 1, documentPageSize })
                  }
                />
              ) : null}
            </section>
          </TabsContent>
        ) : null}
        <TabsContent value='retrieve' className='mt-5'>
          <KnowledgeBaseHitTests
            queryDraft={queryDraft}
            submittedQuery={workspace.retrievalQuery}
            settings={{ topK: workspace.topK, score: workspace.score }}
            results={hasSubmittedRetrievalQuery ? (retrieval.data ?? []) : []}
            loading={hasSubmittedRetrievalQuery && retrieval.loading}
            error={
              hasSubmittedRetrievalQuery && retrieval.error
                ? normalizeKnowledgeBaseError(
                    retrieval.error,
                    t('Hit test failed.'),
                  ).message
                : undefined
            }
            onQueryChange={setQueryDraft}
            onSubmit={(nextQuery) => {
              setQueryDraft('');
              if (nextQuery === workspace.retrievalQuery) {
                retrieval.retry();
              } else {
                setWorkspace({ retrievalQuery: nextQuery }, false);
              }
            }}
            onEditQuery={() => setQueryDraft(workspace.retrievalQuery)}
            onSettingsChange={({ topK, score }) =>
              setWorkspace({ topK, score })
            }
            onRetry={retrieval.retry}
            onOpenResult={(result) => {
              const resultIndex = retrieval.data?.indexOf(result);
              if (resultIndex === undefined || resultIndex < 0) return;
              navigate(
                `${knowledgeBaseLiveRoutes.retrieval(base.data!.key, resultIndex)}${location.search}${location.hash}`,
                { state: { from: liveLocationPath(location) } },
              );
            }}
          />
        </TabsContent>
      </Tabs>
      <DocumentSegmentsDrawer
        open={segmentDrawerOpen && !!segmentDocument}
        onOpenChange={(nextOpen) => {
          if (nextOpen) return;
          setSegmentDrawerOpen(false);
          setSegmentDocument(undefined);
          setWorkspace({ segmentDocumentId: undefined });
        }}
        knowledgeBase={base.data}
        document={segmentDocument}
        canMaintain={
          !!segmentDocument && canMaintainKnowledgeBaseDocument(segmentDocument)
        }
        onDocumentRefresh={documents.retry}
        onOpenSegment={(segment) => {
          const activeDocument = segmentDocument;
          if (!activeDocument) return;
          navigate(
            `${knowledgeBaseLiveRoutes.segment(activeDocument.knowledgeBaseKey, activeDocument.id, segment.uid)}${location.search}${location.hash}`,
            {
              state: { from: liveLocationPath(location), segmentDrawer: true },
            },
          );
        }}
      />
      <AlertDialog
        open={!!documentAction}
        onOpenChange={(open) => {
          if (!open && !documentActionPending) setDocumentAction(undefined);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {documentAction?.kind === 'delete'
                ? t('Delete {{count}} {{item}}?', {
                    count: documentAction.documentIds.length,
                    item: t(
                      documentAction.documentIds.length === 1
                        ? 'document'
                        : 'documents',
                    ),
                  })
                : t('Re-index {{count}} {{item}}?', {
                    count: documentAction?.documentIds.length ?? 0,
                    item: t(
                      (documentAction?.documentIds.length ?? 0) === 1
                        ? 'document'
                        : 'documents',
                    ),
                  })}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {documentAction?.kind === 'delete'
                ? t(
                    'This permanently deletes {{count}} selected {{item}} and their segments.',
                    {
                      count: documentAction.documentIds.length,
                      item: t(
                        documentAction.documentIds.length === 1
                          ? 'document'
                          : 'documents',
                      ),
                    },
                  )
                : t(
                    'This submits asynchronous vectorization tasks for {{count}} {{item}}.',
                    {
                      count: documentAction?.documentIds.length ?? 0,
                      item: t(
                        (documentAction?.documentIds.length ?? 0) === 1
                          ? 'document'
                          : 'documents',
                      ),
                    },
                  )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={documentActionPending}>
              {t('Cancel')}
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => void runDocumentAction()}
              disabled={documentActionPending}
            >
              {documentActionPending
                ? t('Submitting…')
                : documentAction?.kind === 'delete'
                  ? t('Delete {{count}} {{item}}', {
                      count: documentAction.documentIds.length,
                      item: t(
                        documentAction.documentIds.length === 1
                          ? 'document'
                          : 'documents',
                      ),
                    })
                  : t('Re-index {{count}} {{item}}', {
                      count: documentAction?.documentIds.length ?? 0,
                      item: t(
                        (documentAction?.documentIds.length ?? 0) === 1
                          ? 'document'
                          : 'documents',
                      ),
                    })}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      {outletContext ? <Outlet context={outletContext} /> : null}
    </main>
  );
}

import { useState, type ReactElement } from 'react';
import { useNotification } from '@refinedev/core';
import { ChevronDown, Ellipsis, Plus, Settings, Trash2 } from 'lucide-react';
import { useLocation, useNavigate } from 'react-router';

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Switch } from '@/components/ui/switch';
import {
  KnowledgeBaseCardGrid,
  KnowledgeBaseDirectoryEmpty,
  KnowledgeBaseDirectoryError,
  KnowledgeBaseDirectorySkeleton,
  PagePagination,
} from '@/extensions/nocobase-ai-knowledge-base-components/index';
import { useKnowledgeBase } from '@/extensions/nocobase-ai-knowledge-base-providers';
import { useKnowledgeBaseService } from '@/extensions/nocobase-ai-knowledge-base-providers';
import type {
  KnowledgeBase,
  KnowledgeBaseType,
} from '@/extensions/nocobase-ai-knowledge-base-providers';
import { knowledgeBaseLiveRoutes } from '../knowledge-base-routes.js';
import { useT } from '@/extensions/nocobase-ai-knowledge-base-components/locales';
import { liveLocationPath } from './url-state.js';
import { KnowledgeBaseEditorSheet } from './knowledge-base-editor-sheet.js';
import { notifyKnowledgeBaseMutationError } from './notifications.js';

const pageSize = 20;

export default function LiveKnowledgeBasesPage(): ReactElement {
  const t = useT();
  const { open: notify } = useNotification();
  const navigate = useNavigate();
  const location = useLocation();
  const service = useKnowledgeBaseService();
  const [page, setPage] = useState(1);
  const [editorOpen, setEditorOpen] = useState(false);
  const [createMenuOpen, setCreateMenuOpen] = useState(false);
  const [createType, setCreateType] = useState<KnowledgeBaseType>('LOCAL');
  const [editing, setEditing] = useState<KnowledgeBase>();
  const [deleting, setDeleting] = useState<KnowledgeBase>();
  const [pendingIds, setPendingIds] = useState<Set<string>>(() => new Set());
  const knowledgeBase = useKnowledgeBase({
    directory: { mode: 'paginated', page, pageSize },
  });
  const directory = knowledgeBase.directory.paginated;
  const rows = directory.data?.rows ?? [];

  const setPending = (record: KnowledgeBase, pending: boolean): void => {
    setPendingIds((current) => {
      const next = new Set(current);
      const id = String(record.id);
      if (pending) next.add(id);
      else next.delete(id);
      return next;
    });
  };

  const updateEnabled = async (
    record: KnowledgeBase,
    enabled: boolean,
  ): Promise<void> => {
    if (pendingIds.has(String(record.id))) return;
    setPending(record, true);
    try {
      await service.updateKnowledgeBase(record.id, { enabled });
      notify?.({
        type: 'success',
        message: enabled
          ? t('Knowledge base enabled')
          : t('Knowledge base disabled'),
      });
      directory.retry();
    } catch (error) {
      notifyKnowledgeBaseMutationError(
        notify,
        t('Unable to update knowledge base'),
        error,
        t('Unable to update knowledge base'),
      );
    } finally {
      setPending(record, false);
    }
  };

  const deleteKnowledgeBase = async (): Promise<void> => {
    const record = deleting;
    if (!record || pendingIds.has(String(record.id))) return;
    setPending(record, true);
    try {
      await service.deleteKnowledgeBase(record.id);
      notify?.({ type: 'success', message: t('Knowledge base deleted') });
      setDeleting(undefined);
      if (rows.length === 1 && page > 1) setPage((current) => current - 1);
      else directory.retry();
    } catch (error) {
      notifyKnowledgeBaseMutationError(
        notify,
        t('Unable to delete knowledge base'),
        error,
        t('Unable to delete knowledge base'),
      );
    } finally {
      setPending(record, false);
    }
  };

  if (directory.loading && !directory.data) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <KnowledgeBaseDirectorySkeleton />
      </main>
    );
  }
  if (directory.error && !directory.data) {
    return (
      <main className='px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
        <KnowledgeBaseDirectoryError
          error={directory.error}
          onRetry={directory.retry}
        />
      </main>
    );
  }

  return (
    <main className='space-y-3 px-4 pb-12 pt-4 sm:px-6 lg:px-8'>
      <header className='flex justify-end'>
        <div onMouseEnter={() => setCreateMenuOpen(true)}>
          <DropdownMenu open={createMenuOpen} onOpenChange={setCreateMenuOpen}>
            <DropdownMenuTrigger
              render={<Button type='button' aria-label={t('Add new')} />}
            >
              <Plus aria-hidden='true' />
              {t('Add new')}
              <ChevronDown aria-hidden='true' />
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align='end'
              className='w-(--anchor-width) min-w-0'
            >
              {(['LOCAL', 'READONLY', 'EXTERNAL'] as const).map((type) => (
                <DropdownMenuItem
                  key={type}
                  onClick={() => {
                    setCreateType(type);
                    setEditing(undefined);
                    setEditorOpen(true);
                    setCreateMenuOpen(false);
                  }}
                >
                  {t(
                    type === 'LOCAL'
                      ? 'Local'
                      : type === 'READONLY'
                        ? 'Read-only'
                        : 'External',
                  )}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>

      {!rows.length ? (
        <KnowledgeBaseDirectoryEmpty />
      ) : (
        <section className='space-y-4'>
          <KnowledgeBaseCardGrid
            items={rows}
            onItemOpen={(item) =>
              navigate(knowledgeBaseLiveRoutes.workspace(item.key), {
                state: { from: liveLocationPath(location) },
              })
            }
            renderMenu={(item) => (
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button
                      type='button'
                      variant='ghost'
                      size='icon-sm'
                      aria-label={t('Knowledge base actions')}
                    />
                  }
                >
                  <Ellipsis aria-hidden='true' />
                </DropdownMenuTrigger>
                <DropdownMenuContent align='end' className='w-36'>
                  <DropdownMenuItem
                    onClick={() => {
                      setEditing(item);
                      setEditorOpen(true);
                    }}
                  >
                    <Settings aria-hidden='true' />
                    {t('Settings')}
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    variant='destructive'
                    onClick={() => setDeleting(item)}
                  >
                    <Trash2 aria-hidden='true' />
                    {t('Delete')}
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            )}
            renderEnabledControl={(item) => (
              <Switch
                checked={item.enabled}
                disabled={pendingIds.has(String(item.id))}
                aria-label={
                  item.enabled
                    ? t('Disable knowledge base')
                    : t('Enable knowledge base')
                }
                onCheckedChange={(enabled) => void updateEnabled(item, enabled)}
              />
            )}
          />
          {(directory.data?.count ?? 0) > pageSize ? (
            <PagePagination
              page={directory.data?.page ?? page}
              pageSize={pageSize}
              total={directory.data?.count ?? 0}
              onPageChange={setPage}
            />
          ) : null}
        </section>
      )}

      <KnowledgeBaseEditorSheet
        open={editorOpen}
        record={editing}
        knowledgeBaseType={createType}
        onOpenChange={(open) => {
          setEditorOpen(open);
          if (!open) setEditing(undefined);
        }}
        onSaved={directory.retry}
      />

      <AlertDialog
        open={!!deleting}
        onOpenChange={(open) => !open && setDeleting(undefined)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t('Delete knowledge base?')}</AlertDialogTitle>
            <AlertDialogDescription>
              {t(
                'This permanently deletes the knowledge base, its documents, segments, and vectors.',
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{t('Cancel')}</AlertDialogCancel>
            <AlertDialogAction
              variant='destructive'
              disabled={!!deleting && pendingIds.has(String(deleting.id))}
              onClick={() => void deleteKnowledgeBase()}
            >
              {t('Delete')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </main>
  );
}

import type { NotificationProvider } from '@refinedev/core';
import { normalizeKnowledgeBaseError } from '@/extensions/nocobase-ai-knowledge-base-providers';

type NotificationOpen = NotificationProvider['open'] | undefined;

export function notifyKnowledgeBaseMutationError(
  notify: NotificationOpen,
  title: string,
  error: unknown,
  fallback: string,
) {
  notify?.({
    type: 'error',
    message: title,
    description: normalizeKnowledgeBaseError(error, fallback).message,
  });
}

import type { ReactElement } from 'react';
import { useParams, useSearchParams } from 'react-router';

import { LoadingState } from '@/extensions/nocobase-ai-knowledge-base-components/app-shell-loading-state';
import { useKnowledgeBase } from '@/extensions/nocobase-ai-knowledge-base-providers';
import RetrievalResultRoute from './retrieval-result-route.js';
import { parseKnowledgeBaseWorkspaceState } from './url-state.js';

export default function RetrievalResultRouteEntry(): ReactElement {
  const { knowledgeBaseKey } = useParams();
  const [search] = useSearchParams();
  const workspace = parseKnowledgeBaseWorkspaceState(search);
  const state = useKnowledgeBase({
    knowledgeBaseKey,
    retrieval: {
      query: workspace.retrievalQuery,
      topK: workspace.topK,
      score: workspace.score,
    },
  });

  if (state.retrieval.loading && !state.retrieval.data) {
    return <LoadingState className='min-h-64' />;
  }

  return <RetrievalResultRoute retrievalResults={state.retrieval.data ?? []} />;
}

import { useLocation, useOutletContext, useParams } from 'react-router';
import { RouteDrawer } from '../extensions/nocobase-route-surfaces/index.js';
import { RetrievalResultDetail } from '@/extensions/nocobase-ai-knowledge-base-components/index';
import { knowledgeBaseLiveRoutes } from '../knowledge-base-routes.js';
import type { KnowledgeBaseWorkspaceOutletContext } from './knowledge-base-workspace-page.js';
import { liveReturnTo } from './url-state.js';
import { useT } from '@/extensions/nocobase-ai-knowledge-base-components/locales';

export default function RetrievalResultRoute({
  retrievalResults: routeResults,
}: {
  retrievalResults?: KnowledgeBaseWorkspaceOutletContext['retrievalResults'];
} = {}) {
  const t = useT();
  const { knowledgeBaseKey, resultIndex } = useParams();
  const location = useLocation();
  const outletContext = useOutletContext<
    KnowledgeBaseWorkspaceOutletContext | undefined
  >();
  const retrievalResults =
    routeResults ?? outletContext?.retrievalResults ?? [];
  const index = Number.parseInt(resultIndex || '', 10);
  const result = Number.isInteger(index) ? retrievalResults[index] : undefined;
  const fallback = knowledgeBaseKey
    ? `${knowledgeBaseLiveRoutes.workspace(knowledgeBaseKey)}${location.search}${location.hash}`
    : knowledgeBaseLiveRoutes.list;
  const closeTo = knowledgeBaseKey
    ? liveReturnTo(
        location.state,
        fallback,
        knowledgeBaseLiveRoutes.workspace(knowledgeBaseKey),
      )
    : fallback;

  return (
    <RouteDrawer
      title={result?.title || result?.filename || t('Retrieval result')}
      closeLabel={t('Close')}
      closeTo={closeTo}
    >
      <div className='p-5'>
        <RetrievalResultDetail result={result} showTitle={false} />
      </div>
    </RouteDrawer>
  );
}

