import { useT } from '@/extensions/nocobase-ai-knowledge-base-components/locales';

export default function UploadController() {
  const { open: notify } = useNotification();
  const t = useT();
  const { knowledgeBaseKey } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const knowledgeBase = useKnowledgeBase({ knowledgeBaseKey });
  const [file, setFile] = useState<File>();
  const [encodings, setEncodings] = useState<string[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string>();
  const isZip = file?.name.toLowerCase().endsWith('.zip') ?? false;
  const base = knowledgeBase.knowledgeBase;
  const documentState = useKnowledgeBaseDocument({
    knowledgeBaseKey: base.data?.key ?? knowledgeBaseKey,
    upload: {
      enabled: !!(base.data?.key ?? knowledgeBaseKey),
      includeConstraints: true,
      includeZipEncodingOptions: isZip,
    },
  });
  const { service } = documentState;
  const constraints = documentState.upload.constraints;
  const encodingOptions = documentState.upload.zipEncodingOptions;

  const fallback = knowledgeBaseKey
    ? `${knowledgeBaseLiveRoutes.workspace(knowledgeBaseKey)}${location.search}${location.hash}`
    : knowledgeBaseLiveRoutes.list;
  const closeTo = knowledgeBaseKey
    ? liveReturnTo(
        location.state,
        fallback,
        knowledgeBaseLiveRoutes.workspace(knowledgeBaseKey),
      )
    : fallback;

  if (base.loading && !base.data) {
    return (
      <main className='p-4 md:p-7'>
        <LoadingState className='min-h-64' />
      </main>
    );
  }
  if (base.error || !base.data) {
    return (
      <main className='p-4 md:p-7'>
        <Empty className='min-h-64 border'>
          <EmptyHeader>
            <EmptyDescription>
              {t('Knowledge base unavailable or not authorized.')}
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      </main>
    );
  }
  const activeBase = base.data;
  if (!canMaintainKnowledgeBaseDocuments(activeBase)) {
    return (
      <main className='p-4 md:p-7'>
        <Empty className='min-h-64 border'>
          <EmptyHeader>
            <EmptyMedia variant='icon'>
              <FileUp aria-hidden='true' />
            </EmptyMedia>
            <EmptyDescription>
              {t('Uploading documents is unavailable for this knowledge base.')}
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      </main>
    );
  }

  const submit = async () => {
    if (!file || submitting) return;
    if (constraints.loading) {
      setError(t('Loading upload requirements. Try again in a moment.'));
      return;
    }
    if (constraints.error || !constraints.data) {
      setError(
        t(
          'Upload requirements are unavailable. The document was not submitted.',
        ),
      );
      return;
    }
    if (
      constraints.data.maxFileSizeBytes &&
      file.size > constraints.data.maxFileSizeBytes
    ) {
      setError(t('This file exceeds the server upload limit.'));
      return;
    }

    setSubmitting(true);
    setError(undefined);
    try {
      const result = await service.uploadDocument({
        knowledgeBaseKey: activeBase.key,
        file,
        ...(isZip && encodings.length
          ? { zipFilenameEncodings: encodings }
          : {}),
      });
      const uploadNotice = isAsyncUploadResult(result)
        ? result.message ||
          t('The upload task was submitted. Indexing may take a few moments.')
        : t('The document was uploaded. Refreshing the document list.');
      notify?.({
        type: 'success',
        message: t('Upload submitted'),
        description: uploadNotice,
      });
      navigate(closeTo);
    } catch (nextError) {
      const message = t('Upload failed');
      notifyKnowledgeBaseMutationError(notify, message, nextError, message);
    } finally {
      setSubmitting(false);
    }
  };

  const allowedExtensions = constraints.data?.acceptedExtensions?.length
    ? constraints.data.acceptedExtensions
    : defaultDocumentExtensions;
  const defaultZipFilenameEncoding = encodingOptions.data?.find(
    (option) => option.isDefault,
  )?.value;
  const dialogError =
    error ||
    (constraints.error
      ? t(
          'Upload requirements are unavailable. The document was not submitted.',
        )
      : undefined);

  return (
    <>
      {encodingOptions.error && isZip ? (
        <div className='px-4 pt-4 md:px-7'>
          <Alert>
            <AlertTitle>{t('ZIP encoding options unavailable')}</AlertTitle>
            <AlertDescription>
              {t(
                'Leave the encoding selection empty or ask the Portal administrator to expose a supported server capability.',
              )}
            </AlertDescription>
          </Alert>
        </div>
      ) : null}
      <UploadDocumentDialog
        open
        onOpenChange={(open) => {
          if (!open) navigate(closeTo);
        }}
        file={file}
        onFileChange={(next) => {
          setFile(next);
          setEncodings([]);
          setError(undefined);
        }}
        zipFilenameEncodings={encodings}
        encodingOptions={encodingOptions.data ?? []}
        defaultZipFilenameEncoding={defaultZipFilenameEncoding}
        onZipFilenameEncodingsChange={(values) =>
          setEncodings(
            Array.from(
              new Set(values.map((value) => value.trim()).filter(Boolean)),
            ),
          )
        }
        onSubmit={() => void submit()}
        submitting={submitting}
        error={dialogError}
        allowedExtensions={allowedExtensions}
        maxFileSizeBytes={constraints.data?.maxFileSizeBytes}
        onFileRejected={(message) => setError(message || undefined)}
      />
    </>
  );
}

const knowledgeBaseDevRoot = '/ai/knowledge-base';

export type LiveListState = {
  page: number;
  query: string;
  view: 'cards' | 'list';
  pageSize: number;
};

export type KnowledgeBaseWorkspaceState = {
  documentPage: number;
  documentPageSize: number;
  retrievalQuery: string;
  topK: number;
  score: number;
  segmentDocumentId?: string;
};
export type LiveRouteState = { from?: string; segmentDrawer?: boolean };

type LocationParts = { pathname: string; search: string; hash: string };

const positive = (value: string | null) =>
  Math.max(1, Number.parseInt(value || '1', 10) || 1);
const clamp = (value: number, minimum: number, maximum: number) =>
  Math.min(maximum, Math.max(minimum, value));
const numeric = (
  value: string | null,
  fallback: number,
  minimum: number,
  maximum: number,
) => {
  if (!value?.trim()) return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? clamp(parsed, minimum, maximum) : fallback;
};
const selectedPageSize = (value: string | null) =>
  value ? Math.round(numeric(value, 10, 1, 100)) : 10;

export function parseLiveListState(search: URLSearchParams): LiveListState {
  const view = search.get('view');
  return {
    page: positive(search.get('page')),
    query: search.get('q') || '',
    view: view === 'list' ? 'list' : 'cards',
    pageSize: selectedPageSize(search.get('pageSize')),
  };
}

export function liveListSearch(state: LiveListState) {
  const params = new URLSearchParams();
  if (state.page > 1) params.set('page', String(state.page));
  if (state.query) params.set('q', state.query);
  if (state.view !== 'cards') params.set('view', state.view);
  if (state.pageSize !== 10) params.set('pageSize', String(state.pageSize));
  const encoded = params.toString();
  return encoded ? `?${encoded}` : '';
}

export function parseKnowledgeBaseWorkspaceState(
  search: URLSearchParams,
): KnowledgeBaseWorkspaceState {
  return {
    documentPage: positive(search.get('documentsPage')),
    documentPageSize: selectedPageSize(search.get('documentPageSize')),
    retrievalQuery: search.get('query') || '',
    topK: Math.round(numeric(search.get('topK'), 4, 1, 1000)),
    score: numeric(search.get('score'), 0.6, 0, 1),
    segmentDocumentId: search.get('segmentsDocument') || undefined,
  };
}

export function knowledgeBaseWorkspaceSearch(
  state: KnowledgeBaseWorkspaceState,
) {
  const params = new URLSearchParams();
  if (state.documentPage > 1)
    params.set('documentsPage', String(state.documentPage));
  if (state.documentPageSize !== 10)
    params.set('documentPageSize', String(state.documentPageSize));
  if (state.retrievalQuery) params.set('query', state.retrievalQuery);
  if (state.topK !== 4) params.set('topK', String(state.topK));
  if (state.score !== 0.6) params.set('score', String(state.score));
  if (state.segmentDocumentId)
    params.set('segmentsDocument', state.segmentDocumentId);
  const encoded = params.toString();
  return encoded ? `?${encoded}` : '';
}

export const liveLocationPath = ({ pathname, search, hash }: LocationParts) =>
  `${pathname}${search}${hash}`;

export const isLiveSegmentDrawerState = (state: unknown) =>
  !!state &&
  typeof state === 'object' &&
  'segmentDrawer' in state &&
  state.segmentDrawer === true;

/** Do not let location state redirect a close action away from this Registry. */
export function liveReturnTo(
  state: unknown,
  fallback: string,
  expectedPrefix?: string,
) {
  const from =
    state &&
    typeof state === 'object' &&
    'from' in state &&
    typeof state.from === 'string'
      ? state.from
      : undefined;
  if (
    from &&
    (from === knowledgeBaseDevRoot ||
      from.startsWith(`${knowledgeBaseDevRoot}/`)) &&
    (!expectedPrefix || from.startsWith(expectedPrefix))
  ) {
    return from;
  }
  return fallback;
}

export {
  aiEmployeePath,
  llmServicePath,
